  "image_category": "SIGN_ILLUSTRATION",
  "summary": "Hình ảnh minh họa biển số S.505b 'Loại xe hạn chế qua cầu' với ba mẫu trọng tải khác nhau (00t, 00t, 00t), dùng để bổ sung cho biển P.106a nhằm chỉ rõ giới hạn trọng tải cho phép trên từng cầu.",
  "items": [
    {
      "identifier": "S.505b - Mẫu 1",
      "visual_or_geometric_features": "Hình chữ nhật ngang, nền trắng, viền đen, bên trong có hình vẽ khối xe tải đơn giản (hình thang nghiêng + hình chữ nhật) và ghi '00t' ở bên phải",
      "meaning_or_specification": "Chỉ loại xe tải chịu hiệu lực của biển báo P.106a với trọng tải toàn bộ xe cho phép là 00t (bao gồm trọng lượng bản thân và hàng hóa), không phụ thuộc vào số lượng trục."
    },
    {
      "identifier": "S.505b - Mẫu 2",
      "visual_or_geometric_features": "Hình chữ nhật ngang, nền trắng, viền đen, bên trong có hình vẽ khối xe tải dài hơn (hai phần nối tiếp) và ghi '00t' ở bên phải",
      "meaning_or_specification": "Chỉ loại xe tải chịu hiệu lực của biển báo P.106a với trọng tải toàn bộ xe cho phép là 00t, phù hợp với cấu hình xe có nhiều trục hoặc chiều dài lớn hơn."
    },
    {
      "identifier": "S.505b - Mẫu 3",
      "visual_or_geometric_features": "Hình chữ nhật ngang, nền trắng, viền đen, bên trong có hình vẽ khối xe tải rất dài (ba phần nối tiếp) và ghi '00t' ở bên phải",
      "meaning_or_specification": "Chỉ loại xe tải chịu hiệu lực của biển báo P.106a với trọng tải toàn bộ xe cho phép là 00t, dành cho các loại xe tải trọng lớn hoặc có cấu hình đặc biệt."
    }
  ]
